def leer_archivo(ruta, default=""):
    """Lee un archivo o devuelve default si hay error."""
    try:
        with open(ruta, "r") as f:
            return f.read()
    except FileNotFoundError:
        print(f"No se encontró {ruta}, devolviendo default")
        return default
    except PermissionError:
        print(f"Sin permisos para leer {ruta}")
        return default
    except Exception as e:
        print(f"Error inesperado: {e}")
        return default

c = leer_archivo("no_existe.txt")
print(f"Contenido: '{c}'")

import time

def leer_con_reintentos(ruta, intentos=3, espera=0.5):
    for i in range(intentos):
        try:
            with open(ruta, "r") as f:
                return f.read()
        except FileNotFoundError:
            print(f"Intento {i+1}: no encontrado, esperando...")
            time.sleep(espera)
    raise FileNotFoundError(f"No se pudo leer {ruta} tras {intentos} intentos")

try:
    contenido = leer_con_reintentos("no_existe.txt", intentos=2)
except FileNotFoundError as e:
    print(f"Error final: {e}")

